diff --git a/src/config/loader.rs b/src/config/loader.rs
index b14210c..27e4825 100644
--- a/src/config/loader.rs
+++ b/src/config/loader.rs
@@ -701,4 +701,50 @@ app_name: ProjectApp
         let config = load_merged_config(temp.path()).unwrap();
         assert_eq!(config.app_name, Some("NoExtends".to_string()));
     }
+
+    #[test]
+    fn parse_config_rejects_unknown_top_level_fields() {
+        let content = r#"
+app_name: MyApp
+bogus_field: should_not_be_here
+"#;
+        let result = parse_config(content, Path::new("test.yml"));
+        assert!(
+            matches!(result, Err(BivvyError::ConfigParseError { .. })),
+            "expected ConfigParseError for unknown field, got: {:?}",
+            result
+        );
+    }
+
+    #[test]
+    fn parse_config_error_message_names_unknown_field() {
+        let content = "stesp: {}";
+        let result = parse_config(content, Path::new("test.yml"));
+        let err = result.unwrap_err();
+        let msg = err.to_string();
+        assert!(
+            msg.contains("stesp"),
+            "error should name the unknown field 'stesp', got: {}",
+            msg
+        );
+    }
+
+    #[test]
+    fn load_merged_config_rejects_unknown_fields_in_project() {
+        let temp = TempDir::new().unwrap();
+        let bivvy_dir = temp.path().join(".bivvy");
+        fs::create_dir_all(&bivvy_dir).unwrap();
+        fs::write(
+            bivvy_dir.join("config.yml"),
+            "app_name: Test\nunknown_key: oops\n",
+        )
+        .unwrap();
+
+        let result = load_merged_config(temp.path());
+        assert!(
+            result.is_err(),
+            "expected error for unknown field in merged config, got: {:?}",
+            result
+        );
+    }
 }
